  return { customer, items: [first, ...others], note, status: "queued" };
}

function* expandTickets({ items }) {
  function ticket(name, index) {
    return { name, index, dose: Recipe.dose(name) };
  }
  for (const { name, quantity = 1 } of items) {
    for (let index = 0; index < quantity; index++) yield ticket(name, index);
  }
}

function* (orders, status = "ready") {
  for (const order of orders) {
    if (order.status === status) yield order;
  }
}

function* itemLines({ items }) {
  function describe({ name, quantity = 1 }) {
    return `${quantity} x ${name}: ${receiptFormatters.money(Recipe.price(name) * quantity)}`;
  }
  for (const item of items) yield describe(item);
}

function* (order, discount = 0, ...fees) {
  yield `Total: ${receiptFormatters.money(priceOrder(order, discount, ...fees))}`;
  if (order.note) yield `Note: ${order.note}`;
}

