  }

  static dose(name) {
    return { espresso: 18, filter: 20 }[name] ?? 0;
  }

  describe(name) {
    return `${name}: ${Recipe.dose(name)}g beans`;
  }

  static preview(name) {
    return Report.render([name]);
  }
}

