    if (!this.canFill(order)) return false;
    for (const { name, quantity = 1 } of order.items) {
      this.beans -= Recipe.dose(name) * quantity;
      this.cups -= quantity;
    }
    return true;
  }

  restock({ beans = 0, cups = 0 } = {}) {
    this.beans += beans;
    this.cups += cups;
